    -- The label and the length of the longest match at the head of the input.
    runDFA :: DFA -> String -> Maybe (Int, Int)
    runDFA (DFA q0 qfs deltas) = loop1 q0 0 Nothing where
        classify :: Char -> Maybe Char
        classify ch = if ch `XSet.member` theAlphabet then Just ch else Nothing
        loop1 :: Int -> Int -> Maybe (Int, Int) -> String -> Maybe (Int, Int)
        loop1 q len latest [] = latest
        loop1 q len latest (ch : str)
            = case XMap.lookup (q, classify ch) deltas of
                Nothing -> latest
                Just p -> len' `seq` case XMap.lookup p qfs of
                    Nothing -> loop1 p len' latest str
                    Just label -> loop1 p len' (Just (label, len')) str
            where
                len' = len + 1
    -- The position of the last of the first len characters, the position after it, and the rest.
    addLoc :: Int -> Int -> Int -> String -> ((Int, Int), (Int, Int), String)
    addLoc len row col (ch : chs)
        | len > 1 = row' `seq` col' `seq` addLoc (len - 1) row' col' chs
        | otherwise = row' `seq` col' `seq` ((row, col), (row', col'), chs)
        where
            row' = if ch == '\n' then row + 1 else row
            col' = if ch == '\n' then 1 else col + 1
    addLoc _ row col [] = ((row, col), (row, col), [])
